import math

MAGIC_NUMBER_ODD = 1
MAGIC_NUMBER_EVEN = 2
ZERO = 0
ONE = 1
ELEMENT_COUNT_MIN_FOR_STD_DEV = 2
HALF_DIVISOR = 2

class Statistics3:
    @staticmethod
    def _is_odd(n):
        return n % MAGIC_NUMBER_ODD == MAGIC_NUMBER_ODD

    @staticmethod
    def _is_even(n):
        return n % MAGIC_NUMBER_EVEN == ZERO

    @staticmethod
    def _calculate_median_odd(sorted_data):
        n = len(sorted_data)
        return sorted_data[n // HALF_DIVISOR]

    @staticmethod
    def _calculate_median_even(sorted_data):
        n = len(sorted_data)
        return (sorted_data[n // HALF_DIVISOR - ONE] + sorted_data[n // HALF_DIVISOR]) / HALF_DIVISOR

    @staticmethod
    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        if Statistics3._is_odd(n):
            return Statistics3._calculate_median_odd(sorted_data)
        return Statistics3._calculate_median_even(sorted_data)

    @staticmethod
    def _count_frequencies(data):
        counts = {}
        for value in data:
            counts[value] = counts.get(value, ZERO) + ONE
        return counts

    @staticmethod
    def _find_max_count(counts):
        return max(counts.values())

    @staticmethod
    def _extract_mode_values(counts, max_count):
        return [value for value, count in counts.items() if count == max_count]

    @staticmethod
    def mode(data):
        counts = Statistics3._count_frequencies(data)
        max_count = Statistics3._find_max_count(counts)
        return Statistics3._extract_mode_values(counts, max_count)

    @staticmethod
    def _calculate_mean(data):
        if len(data) == ZERO:
            return None
        return sum(data) / len(data)

    @staticmethod
    def _calculate_covariance_numerator(x, y, mean_x, mean_y):
        return sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))

    @staticmethod
    def _calculate_potential_denominator(x, y, mean_x, mean_y):
        sum_x_squared = sum((xi - mean_x) ** 2 for xi in x)
        sum_y_squared = sum((yi - mean_y) ** 2 for yi in y)
        return math.sqrt(sum_x_squared * sum_y_squared)

    @staticmethod
    def correlation(x, y):
        n = len(x)
        mean_x = Statistics3._calculate_mean(x)
        mean_y = Statistics3._calculate_mean(y)
        numerator = Statistics3._calculate_covariance_numerator(x, y, mean_x, mean_y)
        denominator = Statistics3._calculate_potential_denominator(x, y, mean_x, mean_y)
        if denominator == ZERO:
            return None
        return numerator / denominator

    @staticmethod
    def mean(data):
        return Statistics3._calculate_mean(data)

    @staticmethod
    def _get_column(data, index):
        return [row[index] for row in data]

    @staticmethod
    def _build_row(i, data):
        row = []
        for j in range(len(data[0])):
            column1 = Statistics3._get_column(data, i)
            column2 = Statistics3._get_column(data, j)
            correlation = Statistics3.correlation(column1, column2)
            row.append(correlation)
        return row

    @staticmethod
    def correlation_matrix(data):
        matrix = []
        for i in range(len(data[0])):
            row = Statistics3._build_row(i, data)
            matrix.append(row)
        return matrix

    @staticmethod
    def _is_insufficient_for_std_dev(n):
        return n < ELEMENT_COUNT_MIN_FOR_STD_DEV

    @staticmethod
    def _calculate_variance(data, mean_value):
        n = len(data)
        return sum((x - mean_value) ** 2 for x in data) / (n - ONE)

    @staticmethod
    def standard_deviation(data):
        n = len(data)
        if Statistics3._is_insufficient_for_std_dev(n):
            return None
        mean_value = Statistics3.mean(data)
        variance = Statistics3._calculate_variance(data, mean_value)
        return math.sqrt(variance)

    @staticmethod
    def _is_invalid_std_dev(std_deviation):
        return std_deviation is None or std_deviation == ZERO

    @staticmethod
    def _calculate_z_scores(data, mean, std_deviation):
        return [(x - mean) / std_deviation for x in data]

    @staticmethod
    def z_score(data):
        mean = Statistics3.mean(data)
        std_deviation = Statistics3.standard_deviation(data)
        if Statistics3._is_invalid_std_dev(std_deviation):
            return None
        return Statistics3._calculate_z_scores(data, mean, std_deviation)
